import java.io.OutputStream;
import java.io.IOException;
import java.io.InputStream;
import java.io.PrintWriter;
import java.util.StringTokenizer;
import java.io.IOException;
import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.InputStream;

/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author xwchen
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        TaskC solver = new TaskC();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskC {
        long[] sum = new long[105];
        long[] pw = new long[105];
        boolean OK = false;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            long w = in.nextLong();
            long m = in.nextLong();
            long p = 1;
            int mx = 0;
            for (int i = 0; i < 100; ++i) {
                sum[i + 1] = p + sum[i];
                pw[i] = p;
                p *= w;
                if (p > 1L << 40) {
                    mx = i;
                    break;
                }
            }
            process(0, m, mx);
            out.println(OK ? "YES" : "NO");
        }

        void process(long cur, long target, int pos) {
            //System.out.println("cur = " + cur + " pos = " + pos);

            if (cur == target) {
                OK = true;
                return;
            }
            long remaining = sum[pos + 1];
            long next = pw[pos];

            //System.out.println("remaining = " + remaining + " next = " + next);
            if (cur - remaining > target) {
            } else if (cur + remaining < target) {
            } else {
                if (cur + sum[pos] < target) {
                    process(cur + next, target, pos - 1);
                } else if (cur - sum[pos] > target) {
                    process(cur - next, target, pos - 1);
                } else {
                    process(cur, target, pos - 1);
                }
            }
        }

    }

    static class InputReader {
        private BufferedReader reader;
        private StringTokenizer tokenizer = new StringTokenizer("");

        public InputReader(InputStream inputStream) {
            this.reader = new BufferedReader(
                    new InputStreamReader(inputStream));
        }

        public String next() {
            while (!tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    e.printStackTrace();
                }
            }
            return tokenizer.nextToken();
        }

        public long nextLong() {
            return Long.parseLong(next());
        }

    }
}


